<template>
  <div class="row">
    <div class="col-md-12 card">
      <div class="panel panel-info">
        <div class="panel-heading">
          <h5>Datos del Socio de Negocio:</h5>
        </div>
        <div class="panel-body">
          <!-- Error message for validation -->
          <div v-if="sapError" class="alert alert-warning" style="margin-bottom: 15px;">
            <i class="el-icon-warning"></i> Por favor ingrese un código SAP / CI antes de continuar.
          </div>
          <div v-if="sedeError" class="alert alert-warning" style="margin-bottom: 15px;">
            <i class="el-icon-warning"></i> Por favor seleccione una sede antes de continuar.
          </div>

          <div class="row">
            <div class="col-md-3 col-md-offset-2">
              <div class="form-group row">
                <label>Codigo SAP / CI:</label>
                <div>
                  <input type="text" placeholder="Codigo SAP" class="form-control" style="text-transform: uppercase;" v-model="formData.SAPId" @keyup.enter="findBP()" @change="ResetForm() ">
                </div>
              </div>
            </div>

            <div class="col-md-4 col-md-offset-2" style="margin-left: 0">
              <button class="btn btn-fill btn-success btn-block"  id="search-person" @click="findBP()" style="margin-top: 25px;">Buscar</button>
            </div>
          </div>

          <div class="row">
            <div class="col-md-2 col-md-offset-2" style="margin-right: 15px;">
              <div class="form-group row">
                <label>Habilitar en:</label>
                <div>
                  <select class="form-control" v-model="formData.Abr">
                    <option disabled value="">Seleccione una sede</option>
                    <option v-for="b in branchAbrs" :key="b" :value="b">{{ b }}</option>
                  </select>
                </div>
              </div>
            </div>

            <div class="col-md-2">
              <div class="form-group row">
                <label>NIT</label>
                <div>
                  <input type="text" placeholder="NIT" class="form-control" v-model="formData.NIT" @change="ResetPerson()" :readonly="readonly">
                </div>
              </div>
            </div>

            <div class="col-md-4 col-md-offset-1">
              <div class="form-group row">
                <label>Nombre Completo</label>
                <div>
                  <input type="text" placeholder="Nombre Completo" class="form-control" v-model="formData.FullName" @change="ResetPerson()"  :readonly="readonly">
                </div>
              </div>
            </div>

            <div class="col-md-7 col-md-offset-2">
              <div class="form-group row">
                <button class="btn btn-fill btn-success btn-block" @click="send()" style="margin-top: 25px;">Habilitar como persona independiente</button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <data-tables
  :url="url2"
  :propsToSearch="propsToSearch"
  :tableColumns="tableColumns"
  :pagination="pagination"
  :actions="action"
  :fuente-p-d-f="fuente">

  <!-- Slot que se inyecta en la columna de acciones -->
  <template slot="buttons" slot-scope="scope">
    <button
      v-if="isDuplicate(scope.queriedData[scope.index])"
      class="btn btn-xs"
      :class="scope.queriedData[scope.index].IsEnabled ? 'btn-danger btn-fill' : 'btn-success btn-fill'"
      @click="toggleCivil(scope.queriedData[scope.index])">
      {{ scope.queriedData[scope.index].IsEnabled ? 'Deshabilitar' : 'Habilitar' }}
    </button>
  </template>
</data-tables>

    </div>
  </div>
</template>

<script>
import axios from 'axios'
import swal from 'sweetalert2'
export default {
  data () {
    return {
      fuente: 'SARAI',
      readonly: true,
      url: '/civil/',
      sapError: false, // Added for SAP validation
      sedeError: false, // Added for sede validation
      formData: {
        FullName: null,
        SAPId: null,
        NIT: null,
        Document: null,
        Abr: ''
      },
      branchAbrs: ['LPZ', 'SCZ', 'CBB', 'TJA', 'ORU', 'EPC', 'SRE', 'TEO', 'UCE'],
      action: true,
      url2: '/CivilbyBranch/0',
      propsToSearch: ['Id', 'FullName', 'Abr', 'Category', 'SAPId', 'NIT'],
      tableColumns: [
        {
          prop: 'Id',
          label: '#',
          minWidth: 25
        },
        {
          prop: 'Abr',
          label: 'Sede',
          minWidth: 25
        },
        {
          prop: 'SAPId',
          label: 'SAPId',
          minWidth: 50
        },
        {
          prop: 'FullName',
          label: 'FullName',
          minWidth: 100
        },
        {
          prop: 'NIT',
          label: 'NIT',
          minWidth: 100
        }
      ],
      pagination: {
        perPage: 5,
        currentPage: 1,
        perPageOptions: [5, 10, 20],
        total: 0
      }
    }
  },
  computed: {
    // Mapa de Ids que son duplicados (mismo FullName + BranchesId)
    duplicateIds () {
      const rows = this.$store.state.crud.data || []
      const groups = {}

      rows.forEach(r => {
        // FullName + BranchesId definen a la persona en la sede
        const fullName = (r.FullName || '').toUpperCase().trim()
        const branchId = r.BranchesId || ''
        const key = fullName + '|' + branchId

        if (!groups[key]) {
          groups[key] = []
        }
        groups[key].push(r)
      })

      const dup = {}
      Object.keys(groups).forEach(key => {
        if (groups[key].length > 1) {
          groups[key].forEach(r => {
            dup[r.Id] = true
          })
        }
      })

      return dup
    }
  },
  methods: {
    successMessage () {
      swal({
        title: `Buen trabajo!`,
        text: 'Se guardaron los cambios!',
        buttonsStyling: false,
        confirmButtonClass: 'btn btn-success btn-fill',
        type: 'success'
      })
    },
    errorMessage (text) {
      swal({
        title: `Ups!`,
        text: text,
        buttonsStyling: false,
        confirmButtonClass: 'btn btn-success btn-fill',
        type: 'error'
      })
    },
    findBP () {
      // Validate SAP code before searching
      if (!this.formData.SAPId || this.formData.SAPId.trim() === '') {
        this.sapError = true;
        return; // Don't proceed if no SAP code is entered
      }
      
      // Reset error state if validation passes
      this.sapError = false;

      axios.post('civilfindInSAP/', { CardCode: this.formData.SAPId })
        .then(response => {
          this.formData.FullName = response.data.FullName
          this.formData.SAPId = response.data.SAPId
          this.formData.NIT = response.data.NIT
          this.formData.Document = response.data.Document
        })
        .catch(error => {
          if (error.response.status === 404) {
            this.errorMessage('Socio de Negocio no valido:\n\t- El Socio de Negocio no existe\n\t- El Socio de Negocio no es Provedor')
          }
          if (error.response.status === 401) {
            this.errorMessage('Socio de Negocio no valido:\n\t- El Socio de Negocio no esta habilitado para su regional')
          }
        })
    },
    ResetForm () {
      this.formData.FullName = null
      this.formData.NIT = null
      this.formData.Document = null
      this.formData.Abr = ''
      this.sapError = false // Reset errors when form is reset
      this.sedeError = false
    },
    ResetPerson () {
      this.formData.Document = null
    },
    send () {
      // Validate SAP code
      if (!this.formData.SAPId || this.formData.SAPId.trim() === '') {
        this.sapError = true;
        return; // Don't proceed if no SAP code is entered
      }
      
      // Validate sede selection
      if (!this.formData.Abr) {
        this.sedeError = true;
        return; // Don't proceed if no sede is selected
      }
      
      // Reset error states if validation passes
      this.sapError = false;
      this.sedeError = false;

      const payload = {
        SAPId: this.formData.SAPId,
        Abr: this.formData.Abr
      }
      axios.post('civil/', payload)
        .then(response => {
          this.successMessage()
          this.formData.SAPId = null
          this.$store.dispatch('crud/loadData', this.url2)
          this.ResetForm()
        })
        .catch(error => {
          if (error.response.status === 401) {
            this.errorMessage('Su usuario no tiene permisos para usar este socio de negocio')
          }
          if (error.response.status === 409) {
            this.errorMessage('Socio de Negocio no valido:\n\t- El Socio de Negocio ya existe')
          }
        })
    },
    isDuplicate (row) {
      return !!this.duplicateIds[row.Id]
    },

    // NUEVO: habilitar / deshabilitar
    toggleCivil (row) {
  console.log('toggleCivil CLICKED, row:', row)

  // Solo permitir si realmente es duplicado
  if (!this.isDuplicate(row)) {
    console.warn('No es duplicado, no se hace nada')
    this.errorMessage('Solo se pueden (des)habilitar registros duplicados en la misma sede.')
    return
  }

  const newStatus = !row.IsEnabled
  console.log('Nuevo estado que se enviará:', newStatus)

  // Confirmación simple del navegador (para descartar problemas con sweetalert2)
  if (!window.confirm(`¿Seguro que deseas ${newStatus ? 'habilitar' : 'deshabilitar'} a ${row.FullName} en la sede ${row.Abr}?`)) {
    console.log('Usuario canceló en window.confirm')
    return
  }

  axios.post('CivilChangeStatus', {
    Id: row.Id,
    IsEnabled: newStatus
  })
    .then(() => {
      console.log('Respuesta OK de civil/ChangeStatus')
      this.successMessage()
      this.$store.dispatch('crud/loadData', this.url2)
    })
    .catch(error => {
      console.error('Error en civil/ChangeStatus:', error)
      if (error.response && error.response.status === 401) {
        this.errorMessage('No tiene permisos para modificar este registro.')
      } else if (error.response && error.response.status === 404) {
        this.errorMessage('El registro ya no existe.')
      } else {
        this.errorMessage('Ocurrió un error al cambiar el estado.')
      }
    })
}

  }
}
</script>
<style>
</style>


